import { useForm } from 'react-hook-form'
import { z } from 'zod'
import { zodResolver } from '@hookform/resolvers/zod'
import { useNavigate } from 'react-router-dom'
import { toast } from 'sonner'

const schema = z.object({ email: z.string().email(), password: z.string().min(8) })
type FormData = z.infer<typeof schema>

export function AcceptInvitePage() {
  const navigate = useNavigate()
  const { register, handleSubmit, formState: { isSubmitting } } = useForm<FormData>({ resolver: zodResolver(schema) })

  const onSubmit = async (_data: FormData) => {
    toast.success('Invitation accepted! Welcome aboard.')
    navigate('/app/home')
  }

  return (
    <div className="bg-surface rounded-2xl border border-border p-8 shadow-sm">
      <h1 className="text-xl font-semibold mb-1">Accept invitation</h1>
      <p className="text-sm text-muted-foreground mb-6">You've been invited to join a workspace.</p>
      <form onSubmit={handleSubmit(onSubmit)} className="flex flex-col gap-4">
        <div>
          <label className="text-sm font-medium block mb-1.5">Email</label>
          <input {...register('email')} type="email" className="w-full rounded-lg border border-border bg-background px-3 py-2 text-sm outline-none focus:border-accent" />
        </div>
        <div>
          <label className="text-sm font-medium block mb-1.5">Set password</label>
          <input {...register('password')} type="password" className="w-full rounded-lg border border-border bg-background px-3 py-2 text-sm outline-none focus:border-accent" />
        </div>
        <button type="submit" disabled={isSubmitting} className="w-full bg-accent text-accent-foreground rounded-lg py-2.5 text-sm font-medium hover:opacity-90 disabled:opacity-50">
          {isSubmitting ? '...' : 'Accept invite'}
        </button>
      </form>
    </div>
  )
}
